<?php
declare(strict_types=1);require_once __DIR__.'/xlsx_family_import.php';
function docx_case_preview(mysqli $conn,string $path):array{
 $zip=new ZipArchive();if($zip->open($path)!==true)throw new RuntimeException('DOCX cannot be opened.');$xml=$zip->getFromName('word/document.xml');$zip->close();if(!$xml)throw new RuntimeException('DOCX document content missing.');$dom=new DOMDocument();$dom->loadXML($xml,LIBXML_NONET);$xp=new DOMXPath($dom);$text=static function(DOMNode $node)use($xp){$s='';foreach($xp->query('.//*[local-name()="t"]',$node)as$t)$s.=$t->textContent;return trim($s);};
 $tables=[];foreach($xp->query('//*[local-name()="tbl"]')as$tbl){$data=[];foreach($xp->query('./*[local-name()="tr"]',$tbl)as$tr){$cells=$xp->query('./*[local-name()="tc"]',$tr);if($cells->length>=2)$data[$text($cells->item(0))]=$text($cells->item(1));}$tables[]=$data;}
 $descriptions=[];$participants=[];$mode='';foreach($xp->query('//*[local-name()="body"]/*[local-name()="p"]')as$p){$v=$text($p);if($v==='')continue;if(str_starts_with($v,'Description of the Case:')){$mode='description';$tail=trim(substr($v,24));if($tail!=='')$descriptions[]=$tail;continue;}if(str_starts_with($v,'Persons Involved:')){$mode='persons';$participants[]=array_values(array_filter(array_map('trim',preg_split('/\R/u',trim(substr($v,17))))));continue;}if($mode==='description'){$descriptions[]=$v;$mode='';}elseif($mode==='persons'){if(!$participants)$participants[]=[];$participants[array_key_last($participants)][]=$v;}}
 $affs=[];foreach($conn->query("SELECT id,name FROM ip_affiliations WHERE status='active'")->fetch_all(MYSQLI_ASSOC)as$a)$affs[strtolower($a['name'])]=$a;$types=[];foreach($conn->query("SELECT id,code,name FROM case_types WHERE status='active'")->fetch_all(MYSQLI_ASSOC)as$t)$types[strtolower($t['name'])]=$t;
 $out=['total'=>count($tables),'valid'=>0,'warning'=>0,'invalid'=>0,'duplicates'=>0,'types'=>[],'issues'=>[],'rows'=>[]];foreach($tables as$i=>$t){$get=static function(array$t,string$key){foreach($t as$k=>$v)if(strtolower(trim($k))===strtolower($key))return normalize_source_text($v);return null;};$name=$get($t,'Full Name');$title=$get($t,'Case Title / Subject');$typeRaw=preg_replace('/^[^A-Za-z]+/u','',(string)$get($t,'Type of Case'));$type=$types[strtolower(trim($typeRaw))]??null;$affRaw=$get($t,'Tribe / IP Group Affiliation');$aff=$affRaw?$affs[strtolower($affRaw)]??null:null;$fatal=[];$warnings=[];if(!$name)$fatal[]='applicant name missing';if(!$title)$fatal[]='case title missing';if(!$type)$fatal[]='unknown case type';if($affRaw&&!$aff)$warnings[]='unknown applicant affiliation';[$dob,$dobIssue]=normalize_import_date($get($t,'Date of Birth'));[$incident,$incidentIssue]=normalize_import_date($get($t,'Date of Incident'));if($dobIssue)$warnings[]='applicant date of birth not recognized';if($incidentIssue)$warnings[]='incident date not recognized';$duplicate=false;if($name&&$title&&$type){$stmt=$conn->prepare('SELECT COUNT(*) FROM case_applications WHERE LOWER(applicant_fullname)=LOWER(?) AND LOWER(case_title)=LOWER(?) AND case_type=? AND (incident_date<=>?)');$stmt->bind_param('ssss',$name,$title,$type['code'],$incident);$stmt->execute();$duplicate=(int)$stmt->get_result()->fetch_row()[0]>0;if($duplicate){$warnings[]='probable existing case duplicate';$out['duplicates']++;}}
  $people=[];foreach($participants[$i]??[]as$line){if(preg_match('/^(.+?)\s+[–—-]\s+(Complainant|Respondent|Witness)$/iu',$line,$m))$people[]=['name'=>normalize_source_text($m[1]),'role'=>strtolower($m[2])];} $rep=$get($t,'Representative Name');if($rep)$people[]=['name'=>$rep,'role'=>'representative','relationship'=>$get($t,'Relationship'),'contact'=>$get($t,'Contact Number')];$status=$fatal?'invalid':($warnings?'warning':'valid');$out[$status]++;if($typeRaw)$out['types'][$typeRaw]=($out['types'][$typeRaw]??0)+1;if($fatal||$warnings)$out['issues'][]=['case'=>$i+1,'status'=>$status,'issues'=>array_merge($fatal,$warnings)];$out['rows'][]=['source_reference'=>'CASE-'.($i+1),'status'=>$status,'case'=>['applicant_fullname'=>$name,'applicant_gender'=>normalize_source_sex($get($t,'Gender')),'applicant_dob'=>$dob,'applicant_contact'=>$get($t,'Contact Number'),'applicant_email'=>$get($t,'Email'),'applicant_address'=>$get($t,'Complete Address'),'applicant_affiliation_id'=>$aff['id']??null,'rep_name'=>$rep,'rep_relationship'=>$get($t,'Relationship'),'rep_contact'=>null,'case_title'=>$title,'case_type'=>$type['code']??null,'case_type_id'=>$type['id']??null,'incident_date'=>$incident,'incident_location_text'=>$get($t,'Location'),'case_description'=>$descriptions[$i]??null],'participants'=>$people];}
 return$out;
}
